// OpenAI Chat Completions 호출 (Node built-in https 사용 — sandbox 안에서 fetch 미지원)
const https = require('https');
const upstream = $input.first().json;
const cleanedText = upstream._cleanedText || '';
const apiTitle = upstream.plcyNm || '';

const schema = {
  type: "object",
  properties: {
    supportTarget:         { type: ["string","null"] },
    supportContent:        { type: ["string","null"] },
    applyMethod:           { type: ["string","null"] },
    requiredDocuments:     { type: ["string","null"] },
    deadlineNote:          { type: ["string","null"] },
    policyOverview:        { type: ["string","null"] },
    eligibilityCriteria:   { type: ["string","null"] },
    operatingOrganization: { type: ["string","null"] },
    contactPhone:          { type: ["string","null"] },
    confidence:            { type: "number", minimum: 0, maximum: 1 }
  },
  required: [
    "supportTarget","supportContent","applyMethod","requiredDocuments","deadlineNote",
    "policyOverview","eligibilityCriteria","operatingOrganization","contactPhone",
    "confidence"
  ],
  additionalProperties: false
};

const systemMsg = `너는 한국 청년 정책 안내 페이지의 본문을 읽고 핵심 구조화 정보를 뽑는다.
- 텍스트에 명시되지 않은 내용을 임의로 만들지 마라. 모르면 null.
- policyOverview: 정책이 어떤 것인지 1~2문장 요약(목적·대상·내용).
- supportTarget: 지원 대상.
- eligibilityCriteria: 지원자격 (연령/조건/제외 등).
- supportContent: 지원 내용.
- applyMethod: 신청 방법.
- requiredDocuments: 제출 서류.
- deadlineNote: 신청 기간/마감 안내.
- operatingOrganization: 운영기관 또는 주관기관. "운영기관"·"주관기관"·"담당부서" 라벨 주변에서.
- contactPhone: 문의 전화번호.
- confidence: 입력 정보가 정책 안내 문서로서 충분한 정도를 0~1 로 자체 평가.
출력은 JSON 만. 자연어 설명 금지.`;

const userMsg = `원본 API title: ${apiTitle}\n\n외부 페이지 본문:\n${cleanedText}`;

const reqBody = JSON.stringify({
  model: "gpt-4o-mini",
  response_format: {
    type: "json_schema",
    json_schema: { name: "policy_enrichment", strict: true, schema: schema }
  },
  messages: [
    { role: "system", content: systemMsg },
    { role: "user", content: userMsg }
  ]
});

function callOpenAI() {
  return new Promise((resolve) => {
    const req = https.request({
      method: 'POST',
      hostname: 'api.openai.com',
      path: '/v1/chat/completions',
      headers: {
        'Authorization': `Bearer ${$env.OPENAI_API_KEY}`,
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(reqBody)
      },
      timeout: 30000
    }, (res) => {
      let chunks = [];
      res.on('data', c => chunks.push(c));
      res.on('end', () => {
        const body = Buffer.concat(chunks).toString('utf8');
        if (res.statusCode >= 200 && res.statusCode < 300) {
          try { resolve({ ok: true, data: JSON.parse(body) }); }
          catch (e) { resolve({ ok: false, error: 'parse: ' + e.message }); }
        } else {
          resolve({ ok: false, error: `HTTP ${res.statusCode}: ${body.slice(0,200)}` });
        }
      });
    });
    req.on('error', e => resolve({ ok: false, error: 'req error: ' + e.message }));
    req.on('timeout', () => { req.destroy(); resolve({ ok: false, error: 'timeout' }); });
    req.write(reqBody);
    req.end();
  });
}

const result = await callOpenAI();
return [{
  json: {
    ...upstream,
    _llmResponse: result.ok ? result.data : null,
    _llmError: result.ok ? null : result.error
  }
}];

const upstream = $('boilerplate 제거 + 첨부 후보').first()?.json || $input.first().json;
const llmItem = $input.first().json;

let parsed = null;
let status = null;
let confidence = null;
let sections = null;

const llmError = llmItem._llmError;
const llmResponse = llmItem._llmResponse;

if (llmError) {
  status = 'LLM_FAILED';
} else if (!llmResponse) {
  status = 'PARSE_FAILED';
} else {
  const content = llmResponse?.choices?.[0]?.message?.content;
  if (!content) {
    status = 'PARSE_FAILED';
  } else {
    try {
      parsed = typeof content === 'string' ? JSON.parse(content) : content;
    } catch (e) {
      parsed = null;
    }
    if (!parsed || typeof parsed.confidence !== 'number') {
      status = 'PARSE_FAILED';
    } else {
      confidence = parsed.confidence;
      sections = {
        supportTarget:         parsed.supportTarget || null,
        supportContent:        parsed.supportContent || null,
        applyMethod:           parsed.applyMethod || null,
        requiredDocuments:     parsed.requiredDocuments || null,
        deadlineNote:          parsed.deadlineNote || null,
        policyOverview:        parsed.policyOverview || null,
        eligibilityCriteria:   parsed.eligibilityCriteria || null,
        operatingOrganization: parsed.operatingOrganization || null,
        contactPhone:          parsed.contactPhone || null
      };
      status = confidence >= 0.6 ? 'OK' : 'LOW_CONFIDENCE';
    }
  }
}

const enrichment = {
  sourceUrl: upstream._enrichUrl,
  fetchedAt: new Date().toISOString(),
  extractor: 'openai:gpt-4o-mini',
  confidence,
  status,
  sections,
  extraAttachments: upstream._extraAttachments || []
};

return [{ json: { ...upstream, _enrichment: enrichment } }];
